import feedparser
import time
from datetime import datetime, timedelta

from lfx.custom.custom_component.component import Component
from lfx.io import MultilineInput, Output
from lfx.schema.message import Message

class MultiRSSParser(Component):
    display_name = "Quét RSS Hàng Loạt"
    description = "Lấy tin tức từ nhiều RSS feed"
    name = "multi_rss_parser"


    inputs = [
        MultilineInput(
            name="rss_urls",
            display_name="RSS URLs",
            info="Mỗi URL RSS một dòng"
        )
    ]

    outputs = [
        Output(
            display_name="News Output",
            name="data",
            method="parse_feeds"
        )
    ]

    def parse_feeds(self) -> Message:
        urls = [
            url.strip()
            for url in self.rss_urls.split("\n")
            if url.strip()
        ]
    
        now = datetime.now()
        at_24h_earlier = now - timedelta(days=1)
    
        seen_titles = set()
        results = []
    
        for url in urls:
            try:
                feed = feedparser.parse(url)
    
                for entry in feed.entries:
                    if (
                        hasattr(entry, "published_parsed")
                        and entry.published_parsed
                    ):
                        pub_date = datetime.fromtimestamp(
                            time.mktime(entry.published_parsed)
                        )
    
                        if pub_date < at_24h_earlier:
                            continue
    
                    title = entry.get("title", "").strip()
                    link = entry.get("link", "")
    
                    if title and title not in seen_titles:
                        seen_titles.add(title)
    
                        summary = entry.get("summary", "")[:200]
    
                        results.append(
                            f"- Tiêu đề: {title}\n"
                            f"  Link: {link}\n"
                            f"  Tóm tắt: {summary}..."
                        )
    
            except Exception:
                continue
    
        final_text = "\n\n".join(results)
    
        if not final_text:
            final_text = "Không có tin tức AI nào mới trong 24h qua."
    
        return Message(text=final_text)

import requests
from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, SecretStrInput, StrInput, Output
from lfx.schema.message import Message

class TelegramSender(Component):
    display_name = "Gửi Telegram"
    description = "Nhận văn bản từ LLM và gửi thẳng về Telegram cá nhân."
    name = "telegram_sender"

    inputs = [
        MessageTextInput(
        name="input_message",
        display_name="Tin nhắn"
        ),

        SecretStrInput(
        name="bot_token",
        display_name="Bot Token"
        ),

        StrInput(
        name="chat_id",
        display_name="Chat ID"
        )

    ]

    outputs = [
        Output(
            display_name="Result",
            name="result",
            method="send_message"
    )
    ]


    def send_message(self) -> Message:
        # Lấy nội dung văn bản từ input (do Groq truyền vào)
        text_to_send = self.input_message

        # Trích xuất chuỗi văn bản nếu đầu vào là một đối tượng Message
        if isinstance(text_to_send, Message):
            text_to_send = text_to_send.text

        # Cấu hình gọi API Telegram
        url = f"https://api.telegram.org/bot{self.bot_token}/sendMessage"
        
        payload = {
            "chat_id": self.chat_id,
            "text": text_to_send,
            "parse_mode": "HTML", 
            "disable_web_page_preview": True 
        }

        try:
            response = requests.post(url, json=payload)
            data = response.json()
            
            if data.get("ok"):
                return Message(text="Đã gửi tin nhắn Telegram thành công!")
            else:
                error_msg = data.get("description", "Lỗi không xác định")
                return Message(text=f"Lỗi gửi Telegram: {error_msg}")
        except Exception as e:
            return Message(text=f"Lỗi kết nối: {str(e)}")
